content.text:
{
  "name": "多通道 xMAP 多道分析系统",
  "name_en": "Multi-channel xMAP MCA system",
  "manufacturer": "XIA",
  "description": "基于 xMAP/DXP 电子学的多通道多道分析器（MCA）能谱采集系统，可同时处理多个探测通道的计数率、ROI 积分和完整能谱数据，常用于 X 射线荧光能谱、扫描测量和面扫描实验。",
  "description_en": "A multi-channel MCA spectroscopy system based on xMAP/DXP electronics, used to acquire count rates, ROI integrals, and full spectra from multiple detector channels simultaneously. It is commonly used for X-ray fluorescence spectroscopy, scanning measurements, and mapping experiments.",
  "tag_hints": [
    "multi-channel analyzer",
    "xMAP DXP",
    "X-ray fluorescence",
    "ROI counting",
    "spectral acquisition",
    "mapping scan"
  ],
  "actions": [
    {
      "action_name": "auto-ContinuousMode",
      "description": "将设备设为连续采集模式，用于实时读数。",
      "description_en": "Set the device to continuous acquisition mode for live readout."
    },
    {
      "action_name": "auto-NDArrayMode",
      "description": "将设备设为阵列数据采集模式，用于扫描过程中的帧数组采集。",
      "description_en": "Set the device to array-data acquisition mode for collecting frame arrays during scans."
    },
    {
      "action_name": "auto-ROIMode",
      "description": "将设备设为 ROI 采集模式，用于扫描时保存感兴趣区积分数据。",
      "description_en": "Set the device to ROI acquisition mode for saving region-of-interest integrals during scans."
    },
    {
      "action_name": "auto-ScalerMode",
      "description": "将设备设为标量计数模式，用于步进扫描计数。",
      "description_en": "Set the device to scaler mode for step-scan counting."
    },
    {
      "action_name": "auto-arm",
      "description": "使设备进入待采集状态。",
      "description_en": "Arm the device for acquisition."
    },
    {
      "action_name": "auto-config_filesaver",
      "description": "配置数据文件保存参数。",
      "description_en": "Configure data file saving settings."
    },
    {
      "action_name": "auto-connect_counters",
      "description": "连接并配置计数通道。",
      "description_en": "Connect and configure the counting channels."
    },
    {
      "action_name": "auto-disarm",
      "description": "解除设备待采集状态。",
      "description_en": "Disarm the device."
    },
    {
      "action_name": "auto-file_write_complete",
      "description": "检查数据文件写入是否完成。",
      "description_en": "Check whether data file writing is complete."
    },
    {
      "action_name": "auto-finish_capture",
      "description": "结束当前采集并完成缓存数据处理。",
      "description_en": "Finish the current capture and complete buffered data handling."
    },
    {
      "action_name": "auto-post_scan",
      "description": "在扫描结束后执行收尾操作。",
      "description_en": "Perform post-scan cleanup after a scan."
    },
    {
      "action_name": "auto-pre_scan",
      "description": "在扫描开始前准备设备。",
      "description_en": "Prepare the device before a scan."
    },
    {
      "action_name": "auto-save_arraydata",
      "description": "将阵列采集数据保存到文件。",
      "description_en": "Save acquired array data to a file."
    },
    {
      "action_name": "auto-save_calibration",
      "description": "将校准信息保存到文件。",
      "description_en": "Save calibration information to a file."
    },
    {
      "action_name": "auto-set_dwelltime",
      "description": "设置每帧驻留时间。",
      "description_en": "Set the dwell time per frame."
    },
    {
      "action_name": "auto-start",
      "description": "开始采集数据。",
      "description_en": "Start data acquisition."
    },
    {
      "action_name": "auto-stop",
      "description": "停止采集数据。",
      "description_en": "Stop data acquisition."
    },
    {
      "action_name": "auto-get_calib",
      "description": "获取校准信息。",
      "description_en": "Get calibration information."
    },
    {
      "action_name": "auto-get_rois",
      "description": "获取已定义的 ROI 信息。",
      "description_en": "Get the defined ROI information."
    },
    {
      "action_name": "auto-roi_calib_info",
      "description": "获取 ROI 与校准信息。",
      "description_en": "Get ROI and calibration information."
    },
    {
      "action_name": "auto-restore_rois",
      "description": "恢复 ROI 设置。",
      "description_en": "Restore ROI settings."
    },
    {
      "action_name": "auto-next_pixel",
      "description": "将面扫描采集推进到下一个像素。",
      "description_en": "Advance mapping acquisition to the next pixel."
    },
    {
      "action_name": "auto-finish_pixels",
      "description": "结束像素采集序列。",
      "description_en": "Finish the pixel acquisition sequence."
    },
    {
      "action_name": "auto-getCurrentPixel",
      "description": "获取当前像素位置。",
      "description_en": "Get the current pixel position."
    },
    {
      "action_name": "auto-readmca",
      "description": "读取当前 MCA 能谱数据。",
      "description_en": "Read the current MCA spectrum data."
    },
    {
      "action_name": "auto-SCAMode",
      "description": "将设备设为单道分析模式。",
      "description_en": "Set the device to single-channel analyzer mode."
    },
    {
      "action_name": "auto-SpectraMode",
      "description": "将设备设为完整能谱采集模式。",
      "description_en": "Set the device to full-spectrum acquisition mode."
    },
    {
      "action_name": "auto-MCAMode",
      "description": "将设备设为多道分析模式。",
      "description_en": "Set the device to multichannel analyzer mode."
    },
    {
      "action_name": "auto-get_next_filename",
      "description": "获取下一个输出文件名。",
      "description_en": "Get the next output filename."
    },
    {
      "action_name": "auto-get_numcaptured",
      "description": "获取已采集的帧数。",
      "description_en": "Get the number of captured frames."
    }
  ]
}

